import {canvas,text,wrap,e} from '../../../embed/definitions/_lab.js';
export {e};
// SVG text coordinates are baselines: row rules use y - 24 to clear the heading glyphs.
export const FIELDS={demand:'Demand signal (%)',risk:'Unresolved safety issues',delay:'Delay (days)'};
export const ACTIONS={continue:'Continue the plan',narrow:'Reduce the scope',test:'Run a small test',pause:'Pause the work'};
export const PRINCIPLES={individual:'Use each person’s rule',safety:'Safety, then evidence, then date',evidence:'Evidence, then date, then safety',delivery:'Date, then safety, then evidence'};
export const ORDERS={safety:['risk','demand','delay'],evidence:['demand','delay','risk'],delivery:['delay','risk','demand']};
export const DISTURBANCES={none:'Nothing changes',delay:'A dependency slips',demand:'Customer evidence changes',risk:'A safety check raises concerns'};
const baseline={demand:70,risk:0,delay:0};
export const SCENARIOS={
  launch:{name:'A shared product launch',description:'Three leads have agreed to launch a fictional booking service. Their decisions affect one shared release.',people:['Mira · product','Jules · delivery','Alex · operations'],joint:true,events:{delay:{values:{delay:7},recipients:[1],detail:'The supplier reports a seven-day slip to Jules.'},demand:{values:{demand:25},recipients:[0],detail:'Mira receives a customer study: 25% would use this version.'},risk:{values:{risk:4,demand:25},recipients:[2],detail:'Alex receives four unresolved safety issues and a weak demand reading (25%).'}}},
  local:{name:'Three independent service pilots',description:'Three leads can test separate local services. Different responses may fit separate remits without blocking each other.',people:['Mira · library pilot','Jules · workshop pilot','Alex · garden pilot'],joint:false,events:{delay:{values:{delay:7},recipients:[1],detail:'Jules learns a shared supplier is seven days late.'},demand:{values:{demand:25},recipients:[0],detail:'Mira receives a study suggesting demand has fallen to 25%.'},risk:{values:{risk:4,demand:25},recipients:[2],detail:'Alex receives four unresolved safety issues and a 25% demand reading.'}}},
  rehearsal:{name:'A routine rehearsal',description:'A fictional event team shares one rehearsal. The disturbance stays within everyone’s stated boundaries, so different reasoning can still produce the same action.',people:['Mira · programme','Jules · production','Alex · venue'],joint:true,events:{delay:{values:{delay:1},recipients:[1],detail:'Jules receives a one-day slip, inside every current boundary.'},demand:{values:{demand:65},recipients:[0],detail:'Mira receives a demand reading of 65%, above every current minimum.'},risk:{values:{risk:0},recipients:[2],detail:'Alex receives a clean check: zero unresolved safety issues.'}}}
};
export function create(scenario='launch'){if(!Object.hasOwn(SCENARIOS,scenario))throw Error('Unknown scenario.');return {scenario,event:'none',revealed:false,beliefs:[{...baseline},{...baseline},{...baseline}],rules:[{priority:'evidence',demand:50,risk:2,delay:10},{priority:'delivery',demand:30,risk:2,delay:2},{priority:'safety',demand:40,risk:0,delay:5}],shared:{demand:false,risk:false,delay:false},principle:'individual',limits:{demand:40,risk:0,delay:5},scope:'local'};}
const num=max=>({type:'integer',minimum:0,maximum:max}),obj=properties=>({type:'object',properties,required:Object.keys(properties),additionalProperties:false}),observations=obj({demand:num(100),risk:num(20),delay:num(30)});
export const stateSchema=obj({scenario:{type:'string',enum:Object.keys(SCENARIOS)},event:{type:'string',enum:Object.keys(DISTURBANCES)},revealed:{type:'boolean'},beliefs:{type:'array',minItems:3,maxItems:3,items:observations},rules:{type:'array',minItems:3,maxItems:3,items:obj({priority:{type:'string',enum:Object.keys(ORDERS)},...observations.properties})},shared:obj({demand:{type:'boolean'},risk:{type:'boolean'},delay:{type:'boolean'}}),principle:{type:'string',enum:Object.keys(PRINCIPLES)},limits:observations,scope:{type:'string',enum:['local','joint']}});
const validNumbers=value=>value&&Object.keys(value).length===3&&Object.entries({demand:100,risk:20,delay:30}).every(([key,max])=>Number.isInteger(value[key])&&value[key]>=0&&value[key]<=max);
export function validate(s){if(!s||typeof s!=='object'||Array.isArray(s)||Object.keys(s).length!==Object.keys(stateSchema.properties).length||Object.keys(s).some(k=>!Object.hasOwn(stateSchema.properties,k)))throw Error('Expected a complete alignment experiment.');if(!Object.hasOwn(SCENARIOS,s.scenario)||!Object.hasOwn(DISTURBANCES,s.event)||typeof s.revealed!=='boolean'||!Object.hasOwn(PRINCIPLES,s.principle)||!['local','joint'].includes(s.scope))throw Error('Unknown situation or policy.');if(!Array.isArray(s.beliefs)||s.beliefs.length!==3||!s.beliefs.every(validNumbers)||!validNumbers(s.limits))throw Error('Invalid evidence or shared limits.');if(!Array.isArray(s.rules)||s.rules.length!==3||s.rules.some(rule=>!rule||Object.keys(rule).length!==4||!Object.hasOwn(ORDERS,rule.priority)||!validNumbers({demand:rule.demand,risk:rule.risk,delay:rule.delay})))throw Error('Invalid decision rule.');if(!s.shared||Object.keys(s.shared).length!==3||Object.keys(FIELDS).some(k=>typeof s.shared[k]!=='boolean'))throw Error('Invalid shared evidence.');return s;}
export function choose(evidence,rule){const trace=[];for(const field of ORDERS[rule.priority]){const triggered=field==='demand'?evidence[field]<rule[field]:evidence[field]>rule[field];trace.push({field,reading:evidence[field],threshold:rule[field],operator:field==='demand'?'<':'>',triggered});if(triggered)return {action:field==='demand'?'test':field==='risk'?'pause':'narrow',trace};}return{action:'continue',trace};}
export function project(s){validate(s);const scenario=SCENARIOS[s.scenario],event=s.event!=='none'&&s.revealed?scenario.events[s.event]:null,actual={...baseline,...event?.values};const people=scenario.people.map((name,i)=>{const evidence={...s.beliefs[i]},sources=Object.fromEntries(Object.keys(FIELDS).map(k=>[k,'starting belief']));if(event?.recipients.includes(i))for(const [k,v] of Object.entries(event.values)){evidence[k]=v;sources[k]='received the new evidence';}for(const k of Object.keys(FIELDS))if(s.shared[k]){evidence[k]=actual[k];sources[k]='shared scenario reading';}const rule=s.principle==='individual'?s.rules[i]:{priority:s.principle,...s.limits},result=choose(evidence,rule);return{name,evidence,sources,rule,...result};});const actions=[...new Set(people.map(p=>p.action))];const disposition=actions.length===1?`All propose: ${ACTIONS[actions[0]].toLowerCase()}.`:s.scope==='joint'?'Different proposals: hold the shared decision for a joint review.':scenario.joint?'Different proposals affect one release: the plan has an unresolved conflict.':'Different proposals can proceed within the separate remits.';return{scenario,event,actual,people,actions,disposition};}
export function replayPolicy(s,pinned){return project({...structuredClone(s),rules:structuredClone(pinned.rules),shared:structuredClone(pinned.shared),principle:pinned.principle,limits:structuredClone(pinned.limits),scope:pinned.scope});}
export function reason(person){return person.trace.map(t=>`${FIELDS[t.field]}: ${t.reading} ${t.operator} ${t.threshold} is ${t.triggered?'true':'false'}`).join('; ')+`. ${ACTIONS[person.action]}.`;}
export function describe(s,pinned){const r=project(s);return `# We’re aligned—until something changes\n\n${r.scenario.name}\n\n${r.event?r.event.detail:s.event==='none'?'No disturbance.':'Disturbance selected; responses not yet revealed.'}\n\n${r.disposition}\n\n${r.people.map(p=>`## ${p.name}\n\n${reason(p)}\n\n${Object.entries(p.evidence).map(([k,v])=>`${FIELDS[k]} ${v} (${p.sources[k]})`).join('; ')}`).join('\n\n')}\n\nShared principle: ${PRINCIPLES[s.principle]}. Decision boundary: ${s.scope==='joint'?'joint review if proposals differ':'local decisions'}.\n\n${pinned?`Pinned policy replay under the current situation, starting beliefs and disturbance: ${replayPolicy(s,pinned).disposition}\n\n`:''}Rules are explicit fictional if/then assumptions, not personality models. Agreement is not scored as good. The model exposes proposed responses, not the real-world outcome of those actions. Inspired by John Cutler: [Shallow vs. Deep Alignment](https://cutlefish.substack.com/p/tbm-215-shallow-vs-deep-alignment) and [Mapping Beliefs](https://cutlefish.substack.com/p/tbm-2453-mapping-beliefs-and-agreeing).\n`;}
export function render(s,ctx={}){const r=project(s);return {summary:r.disposition,svg:canvas('We’re aligned—until something changes',r.scenario.name,ctx,({w,c,top})=>{let y=top,body='';const chars=Math.max(20,Math.floor((w-48)/9)),add=(value,size=18,color=c.ink)=>{body+=text(24,y,value,{width:chars,size,color});y+=wrap(value,chars).length*size*1.4+14;};add(r.event?r.event.detail:s.event==='none'?'No disturbance: proposals use current starting information.':'Disturbance selected. Reveal to inspect the responses.',16,c.muted);for(const p of r.people){body+=`<path d="M24 ${y-24} H${w-24}" stroke="${e(c.line)}"/>`;add(`${p.name} → ${ACTIONS[p.action]}`,20,c.accent);add(reason(p),16);add(Object.keys(FIELDS).map(k=>`${FIELDS[k]} ${p.evidence[k]} (${p.sources[k]})`).join(' · '),14,c.muted);}add(r.disposition,20);add('Different explicit rules and information can produce the same action. Agreement has no goodness score here.',14,c.muted);return{body,end:y};})};}
